export function t(lang, key, vars = {}) {
  const v = S[lang]?.[key] ?? S.en[key];
  return typeof v === 'string' ? v.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '') : v;
}

const humanize = s => (s || '').replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());

// Labels fall back to the raw string so the UI survives the organisers' final taxonomy.
export const careText = (lang, key) => {
  const [label, desc] = S[lang].care[key] || [humanize(key), ''];
  return { label, desc };
};
export const urgencyText = (lang, key) => S[lang].urg[key] || humanize(key);
export const flagText = (lang, key) => S[lang].flag?.[key] || humanize(key);

const HINGLISH = /\b(hai|hain|ho|ko|ka|ki|ke|se|mein|mujhe|meri|mera|nahi|bhi|aur|kya|kab|kaise|kitni|kitne|dard|bukhar|khansi|raha|rahi|papa|mummy|bahut|abhi|kal|din|saal|ji|yeh|umar)\b/gi;
export function detectLang(s = '') {
  if (/[ऀ-ॿ]/.test(s)) return 'hi';
  return (s.match(HINGLISH) || []).length >= 2 ? 'hinglish' : 'en';
}

// Quick-answer chips for a follow-up question, in the question's own language.
// ponytail: keyword rules, not a model; returns no chips for questions they don't recognise.
const CHIP_RULES = [
  ['duration', /how long|since when|kab se|कब से|kitne (din|samay|time)|कितने (दिन|समय)/i],
  ['age', /how old|\bage\b|umar|umra|उम्र|kitne saal|कितने साल/i],
  ['yesno', /^\s*(is|are|do|does|did|has|have|any|can|could|kya)\b|^\s*क्या/i],
];
export function chipsFor(question) {
  const rule = CHIP_RULES.find(([, re]) => re.test(question));
  return rule ? S[detectLang(question)].chips[rule[0]] : [];
}

export function slotLabel(d, lang) {
  const now = new Date();
  const tomorrow = new Date(now.getTime() + 864e5);
  const day = d.toDateString() === now.toDateString() ? t(lang, 'today')
    : d.toDateString() === tomorrow.toDateString() ? t(lang, 'tomorrow')
    : d.toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' });
  return `${day}, ${d.toLocaleTimeString('en-IN', { hour: 'numeric', minute: '2-digit' })}`;
}
